@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/vocab/datatype/datatypeScheme> ;
            sh:resultMessage "skos:definition is required on a CDIF concept scheme." ;
            sh:resultPath skos:definition ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ a sh:PropertyShape ;
                    sh:message "skos:definition is required on a CDIF concept scheme." ;
                    sh:minCount 1 ;
                    sh:path skos:definition ] ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
